// The correct answer must not sit in the same place most of the time. Where the order of the options
// carries no meaning (no numbers, no "none of these"), the correct option is moved to a position derived from the id.
const fixedOrder = (opts) => opts.some((o) => /^[d−–-]|^Etwa d|Nichts davon|kein Subjekt/.test(o));
const spot = (id) => [...id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7) % 4;
